 p=[i for i,c in enumerate(s) if c=='1']
 a=[x-j for j,x in enumerate(p)]
 med=a[len(a)//2]
 return sum(abs(x-med) for x in a)
def brute(s):
 n=len(s); k=s.count('1')
 best=999
 for l in range(n-k+1):
  tar='0'*l+'1'*k+'0'*(n-k-l)
  # min adjacent swaps = sum abs positions
  p=[i for i,c in enumerate(s) if c=='1']; q=[i for i,c in enumerate(tar) if c=='1']
  best=min(best,sum(abs(x-y) for x,y in zip(p,q)))
 return best
