from typing import List

class Solution:
    def maxSubarrays(self, n: int, conflictingPairs: List[List[int]]) -> int:
        ending = [[] for _ in range(n + 1)]
        for idx, (a, b) in enumerate(conflictingPairs):
            if a > b:
                a, b = b, a
            ending[b].append((a, idx))

        first_val = second_val = 0
        first_id = second_id = -1
        gains = [0] * len(conflictingPairs)
        total = 0
        for r in range(1, n + 1):
            for value, idx in ending[r]:
                if value > first_val:
                    second_val, second_id = first_val, first_id
                    first_val, first_id = value, idx
                elif value > second_val:
                    second_val, second_id = value, idx
            total += r - first_val
            if first_id != -1:
                gains[first_id] += first_val - second_val
        return total + max(gains)

