import sys

def main():
    input = sys.stdin.buffer.readline
    N, M, Q = map(int, input().split())
    edges = []
    for _ in range(M):
        a, b, c = map(int, input().split())
        edges.append((a-1, b-1, c))
    queries = []
    closed = [False] * M
    for _ in range(Q):
        q = list(map(int, input().split()))
        if q[0] == 1:
            i = q[1]-1
            closed[i] = True
            queries.append((1, i))
        else:
            queries.append((2, q[1]-1, q[2]-1))
    INF = 10**30
    d = [[INF] * N for _ in range(N)]
    for i in range(N):
        d[i][i] = 0
    for i, (a, b, c) in enumerate(edges):
        if not closed[i]:
            d[a][b] = d[b][a] = c
    for k in range(N):
        dk = d[k]
        for i in range(N):
            dik = d[i][k]
            if dik == INF:
                continue
            di = d[i]
            for j in range(N):
                v = dik + dk[j]
                if v < di[j]:
                    di[j] = v
    ans = []
    for q in reversed(queries):
        if q[0] == 2:
            v = d[q[1]][q[2]]
            ans.append(str(v if v < INF else -1))
        else:
            a, b, c = edges[q[1]]
            to_a = [d[i][a] for i in range(N)]
            to_b = [d[i][b] for i in range(N)]
            for i in range(N):
                di = d[i]
                ia, ib = to_a[i] + c, to_b[i] + c
                for j in range(i, N):
                    nd = ia + to_b[j]
                    v = ib + to_a[j]
                    if v < nd:
                        nd = v
                    if nd < di[j]:
                        di[j] = nd
                        d[j][i] = nd
    print('\n'.join(reversed(ans)))

if __name__ == '__main__':
    main()

