import sys

def main():
    A, B, M = map(int, sys.stdin.buffer.read().split())
    shape = (A,) * (B - 1) + (A - 1,)
    n = A * B - 1
    # Hook-length formula for the number of standard tableaux of this shape.
    hooks = []
    for r, length in enumerate(shape):
        for c in range(length):
            below = sum(1 for rr in range(r + 1, B) if shape[rr] > c)
            hooks.append(length - c + below)
    total = 1
    for v in range(1, n + 1):
        total = total * v % M
    for h in hooks:
        total = total * pow(h, M - 2, M) % M

    # Count tableaux in which x=(B,A-1) precedes y=(1,A).
    start = (0,) * B
    dp = {start: 1}
    for _ in range(n):
        nd = {}
        for p, ways in dp.items():
            for i in range(B):
                if p[i] >= shape[i] or (i and p[i] >= p[i - 1]):
                    continue
                if i == 0 and p[i] == A - 1:  # about to add y
                    if p[B - 1] < A - 1:      # x not present yet
                        continue
                q = p[:i] + (p[i] + 1,) + p[i + 1:]
                nd[q] = (nd.get(q, 0) + ways) % M
        dp = nd
    good = dp.get(shape, 0)
    print(total * good % M)

if __name__ == '__main__':
    main()

