import sys

def count_tableaux(shape, constrained=False, x=None, y=None):
    # Partitions are generated by adding one cell at a time; each path is one SYT.
    start = (0,) * len(shape)
    dp = {start: 1}
    for _ in range(sum(shape)):
        nd = {}
        for p, ways in dp.items():
            for i, cap in enumerate(shape):
                if p[i] >= cap:
                    continue
                if i and p[i] >= p[i-1]:
                    continue
                # Adding the cell y is allowed only if x was already present.
                if constrained and (i + 1, p[i] + 1) == y:
                    xr, xc = x
                    if p[xr - 1] < xc:
                        continue
                q = list(p)
                q[i] += 1
                q = tuple(q)
                nd[q] = nd.get(q, 0) + ways
        dp = nd
    return dp.get(tuple(shape), 0)

def main():
    A, B, M = map(int, sys.stdin.buffer.read().split())
    shape = (A,) * (B - 1) + (A - 1,)
    total = count_tableaux(shape) % M
    # Bottom-row last cell x must precede the top cell of the rightmost column y.
    good = count_tableaux(shape, True, (B, A - 1), (1, A)) % M
    print(total * good % M)

if __name__ == '__main__':
    main()

