class Solution:
    def numberOfWays(self, n: int, x: int, y: int) -> int:
        mod = 10**9 + 7
        limit = min(n, x)
        dp = [0] * (limit + 1)
        dp[0] = 1

        # dp[k] counts assignments of processed performers, weighted by y
        # for each currently occupied stage.
        for i in range(1, n + 1):
            for k in range(min(i, x), 0, -1):
                dp[k] = (k * dp[k] + (x - k + 1) * y * dp[k - 1]) % mod
            dp[0] = 0

        return sum(dp) % mod

