class Solution:
    def countKReducibleNumbers(self, s: str, k: int) -> int:
        length = len(s)

        def steps_to_one(x: int) -> int:
            steps = 0
            while x > 1:
                x = x.bit_count()
                steps += 1
            return steps

        good = [False] * (length + 1)
        for count in range(1, length + 1):
            good[count] = 1 + steps_to_one(count) <= k

        choose = [[0] * (length + 1) for _ in range(length + 1)]
        for i in range(length + 1):
            choose[i][0] = choose[i][i] = 1
            for j in range(1, i):
                choose[i][j] = (choose[i - 1][j - 1] + choose[i - 1][j]) % MOD

        answer = 0
        ones_so_far = 0
        for i, bit in enumerate(s):
            if bit == '1':
                remaining = length - i - 1
                for count in range(1, length + 1):
                    if good[count]:
                        needed = count - ones_so_far
                        if 0 <= needed <= remaining:
                            answer = (answer + choose[remaining][needed]) % MOD
                ones_so_far += 1
        return answer

