import sys
from collections import deque

def solve():
    data=sys.stdin.buffer.read().split()
    n=int(data[0]); rows=[x.decode() for x in data[1:]]
    # predecessors[u][c] lists a with edge a->u labeled c; outgoing masks[v][c]
    pred=[[[] for _ in range(26)] for _ in range(n)]
    out=[[0]*26 for _ in range(n)]
    edges=[]
    for a,row in enumerate(rows):
        for b,ch in enumerate(row):
            if ch!='-':
                c=ord(ch)-97
                pred[b][c].append(a)
                out[a][c] |= 1<<b
                edges.append((a,b))
    dist=[[-1]*n for _ in range(n)]
    seen=[0]*n
    q=deque()
    for i in range(n):
        dist[i][i]=0; seen[i]|=1<<i; q.append((i,i))
    for a,b in edges:
        if dist[a][b]<0:
            dist[a][b]=1; seen[a]|=1<<b; q.append((a,b))
    while q:
        u,v=q.popleft()
        nd=dist[u][v]+2
        for c in range(26):
            mask=out[v][c]
            if not mask: continue
            for a in pred[u][c]:
                fresh=mask & ~seen[a]
                if fresh:
                    seen[a]|=fresh
                    bits=fresh
                    while bits:
                        bit=bits & -bits; bits-=bit
                        b=bit.bit_length()-1
                        dist[a][b]=nd
                        q.append((a,b))
    print('\n'.join(' '.join(map(str,r)) for r in dist))

if __name__=='__main__': solve()

