    if not data:
        return
    H, W, X = data[:3]
    P, Q = data[3] - 1, data[4] - 1
    strengths = data[5:]

    start = P * W + Q
    seen = bytearray(H * W)
    seen[start] = 1
    current = strengths[start]
    frontier = []

    def add(r, c):
        if 0 <= r < H and 0 <= c < W:
            cell = r * W + c
            if not seen[cell]:
                seen[cell] = 1
                heapq.heappush(frontier, (strengths[cell], cell))

    for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
        add(P + dr, Q + dc)

    while frontier:
        value, cell = frontier[0]
        if value * X >= current:
            break
        heapq.heappop(frontier)
        current += value
        r, c = divmod(cell, W)
        for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            add(r + dr, c + dc)

    print(current)

