from typing import List
from math import factorial

class Solution:
    def permute(self, n: int, k: int) -> List[int]:
        odds = (n + 1) // 2
        evens = n // 2

        def ways(o, e, first):
            m = o + e
            if m == 0:
                return 1
            first_count = (m + 1) // 2
            second_count = m // 2
            if first == 1:
                need_o, need_e = first_count, second_count
            else:
                need_e, need_o = first_count, second_count
            if o != need_o or e != need_e:
                return 0
            return factorial(o) * factorial(e)

        total = ways(odds, evens, 1) + ways(odds, evens, 0)
        if k > total:
            return []
        remaining = set(range(1, n + 1))
        o, e = odds, evens
        result = []
        previous = None
        for _ in range(n):
            for x in sorted(remaining):
                if previous is not None and x % 2 == previous % 2:
                    continue
                no = o - (x % 2 == 1)
                ne = e - (x % 2 == 0)
                count = ways(no, ne, 1 - (x % 2))
                if k > count:
                    k -= count
                else:
                    result.append(x)
                    remaining.remove(x)
                    o, e = no, ne
                    previous = x
                    break
        return result

