class Solution:
    def largestPalindrome(self, n: int, k: int) -> str:
        m = (n + 1) // 2
        weights = []
        for i in range(m):
            j = n - 1 - i
            weights.append((pow(10, n - 1 - i, k) + (pow(10, i, k) if i != j else 0)) % k)

        full = (1 << k) - 1
        suffix = [0] * (m + 1)
        suffix[m] = 1
        for i in range(m - 1, -1, -1):
            prev = suffix[i + 1]
            w = weights[i]
            cur = 0
            for d in range(10):
                shift = (d * w) % k
                if shift:
                    cur |= ((prev << shift) | (prev >> (k - shift))) & full
                else:
                    cur |= prev
            suffix[i] = cur

        out = []
        remainder = 0
        for i, w in enumerate(weights):
            lowest = 1 if i == 0 else 0
            for digit in range(9, lowest - 1, -1):
                needed = (-(remainder + digit * w)) % k
                if (suffix[i + 1] >> needed) & 1:
                    out.append(str(digit))
                    remainder = (remainder + digit * w) % k
                    break

        half = ''.join(out)
        if n % 2:
            return half + half[:-1][::-1]
        return half + half[::-1]

