from typing import List
class Seg:
    def __init__(self, n):
        self.n = n
        size = 4 * n + 5
        self.mx = [0] * size
        self.sm = [0] * size
        self.lazy = [None] * size

    def push(self, t, a, b):
        v = self.lazy[t]
        if v is not None and a < b:
            m = (a + b) // 2
            for c, x, y in ((t * 2, a, m), (t * 2 + 1, m + 1, b)):
                self.mx[c] = v
                self.sm[c] = (y - x + 1) * v
                self.lazy[c] = v
            self.lazy[t] = None

    def put(self, ql, qr, v, t=1, a=0, b=None):
        if b is None:
            b = self.n - 1
        if ql > qr:
            return 0
        if ql <= a and b <= qr:
            old = self.sm[t]
            self.mx[t] = v
            self.sm[t] = (b - a + 1) * v
            self.lazy[t] = v
            return old
        self.push(t, a, b)
        m = (a + b) // 2
        old = 0
        if ql <= m:
            old += self.put(ql, qr, v, t * 2, a, m)
        if qr > m:
            old += self.put(ql, qr, v, t * 2 + 1, m + 1, b)
        self.sm[t] = self.sm[t * 2] + self.sm[t * 2 + 1]
        self.mx[t] = max(self.mx[t * 2], self.mx[t * 2 + 1])
        return old

    def find(self, x, ql, qr, t=1, a=0, b=None):
        if b is None:
            b = self.n - 1
        if b < ql or a > qr or self.mx[t] < x:
            return self.n
        if a == b:
            return a
        self.push(t, a, b)
        m = (a + b) // 2
        res = self.find(x, ql, qr, t * 2, a, m)
        if res < self.n:
            return res
        return self.find(x, ql, qr, t * 2 + 1, m + 1, b)

    def get(self, i, t=1, a=0, b=None):
        if b is None:
            b = self.n - 1
        if a == b:
            return self.mx[t]
        self.push(t, a, b)
        m = (a + b) // 2
        if i <= m:
            return self.get(i, t * 2, a, m)
        return self.get(i, t * 2 + 1, m + 1, b)

class Solution:
    def countNonDecreasingSubarrays(self, nums: List[int], k: int) -> int:
        n = len(nums)
        seg = Seg(n)
        right = n - 1
        cost = 0
        answer = 0
        for left in range(n - 1, -1, -1):
            value = nums[left]
            p = seg.find(value, left + 1, right) if left < right else n
            end = right if p == n else p - 1
            if end >= left + 1:
                old_sum = seg.put(left + 1, end, value)
                cost += (end - left) * value - old_sum
            seg.put(left, left, value)
            while cost > k:
                cost -= seg.get(right) - nums[right]
                right -= 1
            answer += right - left + 1
        return answer

