import sys
from functools import cmp_to_key

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n, k = data[0], data[1]
    funcs = []
    idx = 2
    for _ in range(n):
        a, b = data[idx], data[idx + 1]
        idx += 2
        funcs.append((a, b))

    # The optimal application order is increasing (A - 1) / B.
    def compare(x, y):
        return (x[0] - 1) * y[1] - (y[0] - 1) * x[1]

    funcs.sort(key=cmp_to_key(compare))
    dp = [None] * (k + 1)
    dp[0] = 1
    seen = 0
    for a, b in funcs:
        for count in range(min(k, seen + 1), 0, -1):
            if dp[count - 1] is not None:
                value = a * dp[count - 1] + b
                if dp[count] is None or value > dp[count]:
                    dp[count] = value
        seen += 1
    print(dp[k])

