class Solution:
    def maximizeSumOfWeights(self, edges: List[List[int]], k: int) -> int:
        n = len(edges) + 1
        graph = [[] for _ in range(n)]
        for u, v, w in edges:
            graph[u].append((v, w))
            graph[v].append((u, w))

        parent = [-1] * n
        parent[0] = 0
        order = [0]
        for u in order:
            for v, w in graph[u]:
                if parent[v] == -1:
                    parent[v] = u
                    order.append(v)

        # dp0[u]: best subtree value if edge to parent is absent.
        # dp1[u]: best subtree value if edge to parent is present.
        dp0 = [0] * n
        dp1 = [0] * n
        for u in reversed(order):
            base = 0
            gains = []
            for v, w in graph[u]:
                if parent[v] == u:
                    base += dp0[v]
                    gains.append(w + dp1[v] - dp0[v])
            gains.sort(reverse=True)

            total = 0
            count = 0
            best0 = best1 = 0
            for gain in gains:
                if gain <= 0:
                    break
                if count < k:
                    best0 += gain
                if count < k - 1:
                    best1 += gain
                count += 1
            dp0[u] = base + best0
            dp1[u] = base + best1

        return dp0[0]

