class Solution:
    def shortestMatchingSubstring(self, s: str, p: str) -> int:
        a, b, c = p.split('*')
        n = len(s)

        def occurrences(t):
            if not t:
                return list(range(n + 1))

            m = len(t)
            pi = [0] * m
            j = 0
            for i in range(1, m):
                while j and t[i] != t[j]:
                    j = pi[j - 1]
                if t[i] == t[j]:
                    j += 1
                pi[i] = j

            result = []
            j = 0
            for i, ch in enumerate(s):
                while j and ch != t[j]:
                    j = pi[j - 1]
                if ch == t[j]:
                    j += 1
                if j == m:
                    result.append(i - m + 1)
                    j = pi[j - 1]
            return result

        starts_a = occurrences(a)
        starts_b = occurrences(b)
        starts_c = occurrences(c)

        best = n + 1
        for start_b in starts_b:
            # Latest A ending no later than B's start gives the shortest match.
            ia = bisect_right(starts_a, start_b - len(a)) - 1
            # Earliest C starting no earlier than B's end gives the shortest match.
            ic = bisect_left(starts_c, start_b + len(b))
            if ia >= 0 and ic < len(starts_c):
                length = starts_c[ic] + len(c) - starts_a[ia]
                best = min(best, length)

