class Solution:
    def findAnswer(self, parent: List[int], s: str) -> List[bool]:
        n = len(parent)
        children = [[] for _ in range(n)]
        for i in range(1, n):
            children[parent[i]].append(i)

        # Postorder traversal; pushing children in reverse preserves increasing order.
        order = []
        stack = [(0, False)]
        while stack:
            node, visited = stack.pop()
            if visited:
                order.append(node)
            else:
                stack.append((node, True))
                for child in reversed(children[node]):
                    stack.append((child, False))

        position = [0] * n
        for i, node in enumerate(order):
            position[node] = i

        subtree_size = [1] * n
        for node in order:
            if parent[node] != -1:
                subtree_size[parent[node]] += subtree_size[node]

        text = ''.join(s[node] for node in order)

        odd = [0] * n
        left, right = 0, -1
        for i in range(n):
            radius = 1 if i > right else min(odd[left + right - i], right - i + 1)
            while i - radius >= 0 and i + radius < n and text[i - radius] == text[i + radius]:
                radius += 1
            odd[i] = radius
            if i + radius - 1 > right:
                left, right = i - radius + 1, i + radius - 1

        even = [0] * n
        left, right = 0, -1
        for i in range(n):
            radius = 0 if i > right else min(even[left + right - i + 1], right - i + 1)
            while i - radius - 1 >= 0 and i + radius < n and text[i - radius - 1] == text[i + radius]:
                radius += 1
            even[i] = radius
            if i + radius - 1 > right:
                left, right = i - radius, i + radius - 1

        answer = [False] * n
        for node in range(n):
            length = subtree_size[node]
            start = position[node] - length + 1
            if length % 2:
                answer[node] = odd[start + length // 2] >= length // 2 + 1
            else:
                answer[node] = even[start + length // 2] >= length // 2
        return answer

