from typing import List
class Solution:
    def maxEnergyBoost(self, energyDrinkA: List[int], energyDrinkB: List[int]) -> int:
        n = len(energyDrinkA)
        da = [0] * n
        db = [0] * n
        da[0], db[0] = energyDrinkA[0], energyDrinkB[0]
        for i in range(1, n):
            from_b = db[i-2] if i >= 2 else 0
            from_a = da[i-2] if i >= 2 else 0
            da[i] = energyDrinkA[i] + max(da[i-1], from_b)
            db[i] = energyDrinkB[i] + max(db[i-1], from_a)
        return max(da[-1], db[-1])

