from typing import List

class Solution:
    def maxSubarraySum(self, nums: List[int], k: int) -> int:
        # Prefix indices with equal remainder modulo k have a difference
        # divisible by k. Keep the smallest prefix sum seen for each remainder.
        min_prefix = [None] * k
        min_prefix[0] = 0

        prefix = 0
        best = None
        for end, value in enumerate(nums, 1):
            prefix += value
            rem = end % k

            if min_prefix[rem] is not None:
                candidate = prefix - min_prefix[rem]
                if best is None or candidate > best:
                    best = candidate

            if min_prefix[rem] is None or prefix < min_prefix[rem]:
                min_prefix[rem] = prefix

        return best

