class Solution:
    def countPairs(self, nums: List[int]) -> int:
        def reachable(x: int) -> set[int]:
            digits = list(str(x))
            values = {x}
            for i in range(len(digits)):
                for j in range(i + 1, len(digits)):
                    digits[i], digits[j] = digits[j], digits[i]
                    values.add(int(''.join(digits)))
                    digits[i], digits[j] = digits[j], digits[i]
            return values

        reachable_values = [reachable(x) for x in nums]
        return sum(
            1
            for i in range(len(nums))
            for j in range(i)
            if nums[i] in reachable_values[j] or nums[j] in reachable_values[i]
        )

