class Solution:
    def minZeroArray(self, nums: List[int], queries: List[List[int]]) -> int:
        n = len(nums)
        dp = [1] * n  # Bit s is set iff sum s is reachable for that index.
        done = [x == 0 for x in nums]

        if all(done):
            return 0

        for k, (left, right, value) in enumerate(queries, 1):
            for i in range(left, right + 1):
                dp[i] |= dp[i] << value
                dp[i] &= (1 << (nums[i] + 1)) - 1
                if not done[i] and ((dp[i] >> nums[i]) & 1):
                    done[i] = True
            if all(done):
                return k

        return -1

