import heapq

class Solution:
    def minOperations(self, n: int, m: int) -> int:
        digits = len(str(n))
        lo = 10 ** (digits - 1)
        hi = 10 ** digits

        # Sieve all possible values with this digit length.
        is_prime = [True] * hi
        is_prime[0] = is_prime[1] = False
        for p in range(2, int((hi - 1) ** 0.5) + 1):
            if is_prime[p]:
                for x in range(p * p, hi, p):
                    is_prime[x] = False

        if not (lo <= m < hi) or is_prime[n] or is_prime[m]:
            return -1

        powers = [10 ** i for i in range(digits)]
        dist = {n: n}  # Include the starting value in the transformation cost.
        heap = [(n, n)]

        while heap:
            cost, value = heapq.heappop(heap)
            if dist.get(value) != cost:
                continue
            if value == m:
                return cost

            for place in powers:
                digit = (value // place) % 10
                if digit < 9:
                    nxt = value + place
                    if not is_prime[nxt] and cost + nxt < dist.get(nxt, float('inf')):
                        dist[nxt] = cost + nxt
                        heapq.heappush(heap, (cost + nxt, nxt))
                if digit > 0 and (place != powers[-1] or digit > 1):
                    nxt = value - place
                    if not is_prime[nxt] and cost + nxt < dist.get(nxt, float('inf')):
                        dist[nxt] = cost + nxt
                        heapq.heappush(heap, (cost + nxt, nxt))

        return -1

