from typing import List

class Solution:
    def beautifulSplits(self, nums: List[int]) -> int:
        n = len(nums)
        if n < 3:
            return 0

        # z[i] is the longest prefix matching the suffix beginning at i.
        z = [0] * n
        left = right = 0
        for i in range(1, n):
            if i <= right:
                z[i] = min(right - i + 1, z[i - left])
            while i + z[i] < n and nums[z[i]] == nums[i + z[i]]:
                z[i] += 1
            if i + z[i] - 1 > right:
                left, right = i, i + z[i] - 1

        answer = 0
        # For each i, compute LCP(nums[i:], nums[j:]) for all j > i.
        # The previous row supplies the diagonal continuation.
        previous = [0] * (n + 1)
        for i in range(n - 2, 0, -1):
            current = [0] * (n + 1)
            first_matches = z[i] >= i
            for j in range(i + 1, n):
                if nums[i] == nums[j]:
                    current[j] = 1 + previous[j + 1]

                # nums1 is a prefix of nums2 only when nums2 is long enough.
                if (first_matches and j - i >= i) or current[j] >= j - i:
                    answer += 1
            previous = current

        return answer

