class Solution:
    def minCost(self, n: int, cost: List[List[int]]) -> int:
        # A state gives the colors of a symmetric pair of houses.
        colors = [(a, b) for a in range(3) for b in range(3) if a != b]
        dp = [cost[0][a] + cost[n - 1][b] for a, b in colors]

        for i in range(1, n // 2):
            ndp = [10**30] * 6
            for x, (a, b) in enumerate(colors):
                pair_cost = cost[i][a] + cost[n - 1 - i][b]
                for y, (c, d) in enumerate(colors):
                    if a != c and b != d:
                        ndp[x] = min(ndp[x], dp[y] + pair_cost)
            dp = ndp

        return min(dp)

