class Solution:
    def calculateScore(self, s: str) -> int:
        positions = [[] for _ in range(26)]
        score = 0
        for i, ch in enumerate(s):
            c = ord(ch) - ord('a')
            mirror = 25 - c
            if positions[mirror]:
                j = positions[mirror].pop()
                score += i - j
            else:
                positions[c].append(i)
        return score

